8	LockstepResult compare_lockstep_streams(
9	    const std::vector<hybrid_state_v1>& oracle,
10	    const std::vector<hybrid_state_v1>& dut) {
11	  LockstepResult r;
12	  const std::size_t common = std::min(oracle.size(), dut.size());
13	
14	  for (std::size_t k = 0; k < common; ++k) {
15	    const DiffReport d =
16	        diff_states(oracle[k], dut[k], /*compare_trap_cause=*/true);
17	    if (!d.ok()) {
18	      r.diverged = true;
19	      r.record = k;
20	      r.matched = k;
21	      r.oracle_pc = oracle[k].pc;
22	      r.dut_pc = dut[k].pc;
23	      r.diff = d;
24	      return r;
25	    }
26	  }
27	
28	  // Prefix matched. A length difference means one engine took more attempts
29	  // than the other -- a control-flow divergence localized to the first record
30	  // the shorter stream is missing.
31	  if (oracle.size() != dut.size()) {
32	    r.diverged = true;
33	    r.record = common;
34	    r.matched = common;
35	    r.length_mismatch =
36	        "stream length mismatch: oracle has " + std::to_string(oracle.size()) +
37	        " record(s), DUT has " + std::to_string(dut.size()) +
38	        " (matched " + std::to_string(common) + ")";
39	    if (common < oracle.size()) r.oracle_pc = oracle[common].pc;
40	    if (common < dut.size()) r.dut_pc = dut[common].pc;
41	    return r;
42	  }
43	
44	  r.matched = common;
45	  return r;
46	}
