48	std::vector<uint64_t> subdivide_window(uint64_t lo, uint64_t hi, int fanout,
49	                                       uint64_t spacing) {
50	  std::vector<uint64_t> targets;
51	  if (hi <= lo || spacing == 0) return targets;
52	  const uint64_t w = hi - lo;
53	  if (w <= spacing) return targets;  // at the floor; cannot narrow
54	  const uint64_t n =
55	      std::min<uint64_t>(static_cast<uint64_t>(fanout), w / spacing);
56	  if (n < 2) return targets;
57	  for (uint64_t j = 1; j <= n; ++j) {
58	    const uint64_t t = lo + (w * j) / n;  // j==n -> hi
59	    if (targets.empty() || t > targets.back()) targets.push_back(t);
60	  }
61	  return targets;
62	}
