26	class LockstepSession
27	{
28	public:
29	  using RD = ResumeDriver;
30	
31	  struct Config
32	  {
33	    uint64_t arm_pc = 0;
34	    // 0 = unbounded: the stop check (program exit) is the only terminator.
35	    uint64_t max_records = 0;
36	    // Steps allowed between the boot halt and DPC == arm_pc. The reset
37	    // vector normally IS the arm pc (zero pre-steps); the budget bounds a
38	    // mis-specified arm pc instead of stepping forever.
39	    uint64_t pre_arm_step_budget = 1'000'000;
40	  };
41	
42	  // sink(record, k): k counts from 0; record k = state before execution
43	  // attempt k+1. stop(): polled between records; true ends the session
44	  // (e.g. SimControl reported program exit).
45	  using Sink      = std::function<void(const hybrid_state_v1&, uint64_t)>;
46	  using StopCheck = std::function<bool()>;
47	
48	  // scratch_gpa (L26): forwarded to StateDrain for the V dump sweep; defaults
49	  // to the unset sentinel (non-V lock-step records never read it). The
50	  // simulator passes the real mmap-top-page GPA.
51	  LockstepSession(DmiBus& bus, Config cfg, Sink sink, StopCheck stop,
52	                  uint64_t scratch_gpa = kVScratchGpaUnset)
53	      : bus_{bus},
54	        drain_{bus, scratch_gpa},
55	        step_{bus},
56	        cfg_{cfg},
57	        sink_{std::move(sink)},
58	        stop_{std::move(stop)}
59	  {}
60	
61	  // Returns the number of records written.
62	  auto run() -> uint64_t
63	  {
64	    // dmactive 0->1 in its own write, then haltreq (Debug Spec).
65	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
66	    bus_.write(RD::kDmcontrol,
67	               RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
68	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
69	                   "LockstepSession boot halt");
70	    step_.enable();
71	
72	    // Pre-arm: step until the next instruction IS the arm pc.
73	    uint64_t budget = cfg_.pre_arm_step_budget;
74	    while (read_register_64(bus_, regno_csr(RD::kCsrDpc),
75	                            "LockstepSession dpc") != cfg_.arm_pc) {
76	      if (budget-- == 0)
77	        throw std::runtime_error(
78	          "LockstepSession: arm pc 0x" + to_hex(cfg_.arm_pc)
79	          + " not reached within the pre-arm step budget ("
80	          + std::to_string(cfg_.pre_arm_step_budget)
81	          + " steps); wrong --cosim-arm-pc?");
82	      step_.step_one();
83	    }
84	
85	    uint64_t records = 0;
86	    for (;;) {
87	      sink_(drain_.drain_full(), records);
88	      ++records;
89	      if (cfg_.max_records != 0 && records >= cfg_.max_records) break;
90	      if (stop_()) break;
91	      step_.step_one();
92	    }
93	    step_.disable();
94	    return records;
95	  }
96	
97	private:
98	  static auto to_hex(uint64_t v) -> std::string
99	  {
100	    char buf[19];
101	    std::snprintf(buf, sizeof(buf), "%llx",
102	                  static_cast<unsigned long long>(v));
103	    return buf;
104	  }
105	
106	  DmiBus& bus_;
107	  StateDrain drain_;
108	  StepDriver step_;
109	  Config cfg_;
110	  Sink sink_;
111	  StopCheck stop_;
112	};
